CREATE TABLE workspace_summary_revisions ( workspace_id TEXT PRIMARY KEY NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, revision TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))), dirty INTEGER NOT NULL DEFAULT 1 CHECK(dirty IN (0,1)) );
INSERT INTO workspace_summary_revisions(workspace_id) SELECT id FROM workspaces;
CREATE TRIGGER summary_revision_workspace_insert AFTER INSERT ON workspaces BEGIN INSERT INTO workspace_summary_revisions(workspace_id) VALUES(NEW.id); END;
CREATE TRIGGER summary_revision_device_insert AFTER INSERT ON workspace_devices BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=NEW.workspace_id AND dirty=0; END;
CREATE TRIGGER summary_revision_device_update AFTER UPDATE ON workspace_devices BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id IN (OLD.workspace_id,NEW.workspace_id) AND dirty=0; END;
CREATE TRIGGER summary_revision_metrics_insert AFTER INSERT ON health_metrics BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=NEW.workspace_id AND dirty=0; END;
CREATE TRIGGER summary_revision_metrics_update AFTER UPDATE ON health_metrics BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id IN (OLD.workspace_id,NEW.workspace_id) AND dirty=0; END;
CREATE TRIGGER summary_revision_metrics_delete AFTER DELETE ON health_metrics BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=OLD.workspace_id AND dirty=0; END;
CREATE TRIGGER summary_revision_workouts_insert AFTER INSERT ON health_workouts BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=NEW.workspace_id AND dirty=0; END;
CREATE TRIGGER summary_revision_workouts_update AFTER UPDATE ON health_workouts BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id IN (OLD.workspace_id,NEW.workspace_id) AND dirty=0; END;
CREATE TRIGGER summary_revision_workouts_delete AFTER DELETE ON health_workouts BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=OLD.workspace_id AND dirty=0; END;
CREATE TRIGGER summary_revision_syncs_insert AFTER INSERT ON sync_batches BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=NEW.workspace_id AND dirty=0; END;
CREATE TRIGGER summary_revision_syncs_update AFTER UPDATE ON sync_batches BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id IN (OLD.workspace_id,NEW.workspace_id) AND dirty=0; END;
CREATE TRIGGER summary_revision_syncs_delete AFTER DELETE ON sync_batches BEGIN UPDATE workspace_summary_revisions SET revision=lower(hex(randomblob(16))),dirty=1 WHERE workspace_id=OLD.workspace_id AND dirty=0; END;
